<summary>Benchmark harness (throwaway, not committed)</summary>

Drop into `rust/src/text/tests/` and run `cargo test --release -p vllm-text --test <name> -- --ignored --nocapture`.

```rust
// Throwaway timing harness for the token-only PR. Not committed.
use std::path::Path;
use std::sync::Arc;
use std::time::Instant;

use futures::{StreamExt as _, executor::block_on, stream};
use vllm_llm::{FinishReason, GenerateOutput, Logprobs, PositionLogprobs, TokenLogprob};
use vllm_text::output::{TextDecodeOptions, decoded_text_event_stream};
use vllm_tokenizer::{DynTokenizer, HuggingFaceTokenizer};

const TOKENIZER: &str = "/mnt/storage/hf_cache/hub/models--Qwen--Qwen3.6-35B-A3B/snapshots/995ad96eacd98c81ed38be0c5b274b04031597b0/tokenizer.json";
const PROMPT_TOKENS: usize = 8192;
const OUTPUT_TOKENS: usize = 1024;
const TOKENS_PER_UPDATE: usize = 4;
const REQUESTS: usize = 100;

fn outputs(prompt: &Arc<[u32]>, text_ids: &[u32], top_k: usize) -> Vec<GenerateOutput> {
    let ids: Vec<u32> = text_ids.iter().copied().cycle().take(OUTPUT_TOKENS).collect();
    let chunks: Vec<&[u32]> = ids.chunks(TOKENS_PER_UPDATE).collect();
    let last = chunks.len() - 1;
    chunks
        .into_iter()
        .enumerate()
        .map(|(i, chunk)| {
            let mut out = GenerateOutput::for_test(
                (i == 0).then(|| Arc::clone(prompt)),
                chunk.to_vec(),
                (i == last).then_some(FinishReason::Length),
            );
            if top_k > 0 {
                out.logprobs = Some(Logprobs {
                    positions: chunk
                        .iter()
                        .map(|&token_id| PositionLogprobs {
                            entries: (0..=top_k as u32)
                                .map(|rank| TokenLogprob {
                                    token_id: token_id.wrapping_add(rank) % 150_000,
                                    logprob: -(rank as f32),
                                    rank: rank + 1,
                                })
                                .collect(),
                        })
                        .collect(),
                });
            }
            out
        })
        .collect()
}

fn run(tokenizer: &DynTokenizer, all: &[Vec<GenerateOutput>], detokenize: bool) -> f64 {
    let start = Instant::now();
    for outputs in all {
        let events = block_on(
            decoded_text_event_stream(
                "bench".into(),
                Arc::clone(tokenizer),
                stream::iter(outputs.clone().into_iter().map(Ok)),
                TextDecodeOptions {
                    detokenize,
                    ..Default::default()
                },
                true,
            )
            .collect::<Vec<_>>(),
        );
        assert!(events.iter().all(Result::is_ok));
    }
    start.elapsed().as_secs_f64()
}

#[test]
#[ignore]
fn token_only_decode_cost() {
    let tokenizer: DynTokenizer =
        Arc::new(HuggingFaceTokenizer::new(Path::new(TOKENIZER)).expect("load tokenizer"));
    let text = "The quick brown fox jumps over the lazy dog. Rust's ownership model \
                makes concurrent code safer, and incremental detokenization turns \
                token IDs back into UTF-8 text one step at a time. ";
    let text_ids = tokenizer.encode(&text.repeat(64), false).unwrap();
    let prompt: Arc<[u32]> = text_ids.iter().copied().cycle().take(PROMPT_TOKENS).collect();

    for top_k in [0, 5] {
        let all: Vec<_> = (0..REQUESTS).map(|_| outputs(&prompt, &text_ids, top_k)).collect();
        // Warm up both paths.
        run(&tokenizer, &all[..5], true);
        run(&tokenizer, &all[..5], false);
        let text = run(&tokenizer, &all, true);
        let token_only = run(&tokenizer, &all, false);
        let per_tok = |secs: f64| secs * 1e6 / (REQUESTS * OUTPUT_TOKENS) as f64;
        println!(
            "top_k={top_k} prompt={PROMPT_TOKENS} output={OUTPUT_TOKENS} updates_of={TOKENS_PER_UPDATE} \
             requests={REQUESTS}: detokenize=true {:.3} us/token ({:.2} ms/request), \
             detokenize=false {:.3} us/token ({:.2} ms/request), saved {:.1}%",
            per_tok(text),
            text * 1e3 / REQUESTS as f64,
            per_tok(token_only),
            token_only * 1e3 / REQUESTS as f64,
            100.0 * (1.0 - token_only / text)
        );
    }
}
```

